mapper.select:
SELECT b.user_id::text AS ownerId,
       COUNT(*)::numeric AS bookingCount
FROM crm_booking b
WHERE b.user_id IS NOT NULL
  AND b.user_id::text IN

    #{oid}

  AND b.start_time >= #{dayStart}
  AND b.start_time < #{dayEnd}

  AND b.status <> 'cancelled'

GROUP BY b.user_id

SELECT b.booking_id AS bookingId, b.lead_id AS leadId, b.contact_id AS contactId, b.org_id AS orgId, COALESCE(o.short_name, o.full_name) AS orgName, b.booking_name AS bookingName, b.start_time AS startTime, b.end_time AS endTime, b.status AS status, b.mobile_phone AS mobilePhone, b.owner AS owner, b.user_id AS userId, COALESCE(c.full_name, c.name, l.full_name, l.lead_name, b.booking_name) AS subjectName FROM crm_booking b LEFT JOIN crm_org o ON o.org_id = b.org_id LEFT JOIN crm_contact c ON c.contact_id = b.contact_id LEFT JOIN crm_lead l ON l.lead_id = b.lead_id WHERE b.start_time >= #{dayStart} AND b.start_time < #{dayEnd}
AND b.user_id IS NOT NULL AND b.user_id::text IN
#{oid}
AND b.user_id = #{userId}
AND b.status <> 'cancelled'
ORDER BY b.start_time ASC

SELECT l.lead_id AS leadId, COALESCE(l.full_name, l.lead_name) AS leadName, l.user_id::text AS ownerId, l.owner AS ownerName, COALESCE(l.last_followup_at, l.assigned_at, l.create_time) AS lastFollowupAt, EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - COALESCE(l.last_followup_at, l.assigned_at, l.create_time))) / 3600.0 AS idleHours, NULL::float8 AS poolEtaHours FROM crm_lead l WHERE lower(trim(coalesce(l.status, ''))) = 'assigned' AND l.user_id IS NOT NULL
AND l.user_id::text IN
#{oid}
AND COALESCE(l.last_followup_at, l.assigned_at, l.create_time) < (CURRENT_TIMESTAMP - (#{idleHours} || ' hours')::interval) ORDER BY COALESCE(l.last_followup_at, l.assigned_at, l.create_time) ASC LIMIT #{limit}

SELECT l.lead_id AS leadId, COALESCE(l.full_name, l.lead_name) AS leadName, l.user_id::text AS ownerId, l.owner AS ownerName, COALESCE(l.last_followup_at, l.assigned_at, l.create_time) AS lastFollowupAt, EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP - COALESCE(l.last_followup_at, l.assigned_at, l.create_time))) / 3600.0 AS idleHours, EXTRACT(EPOCH FROM ( COALESCE(l.last_followup_at, l.assigned_at, l.create_time) + (#{idleHours} || ' hours')::interval - CURRENT_TIMESTAMP )) / 3600.0 AS poolEtaHours FROM crm_lead l WHERE lower(trim(coalesce(l.status, ''))) = 'assigned' AND l.user_id IS NOT NULL
AND l.user_id::text IN
#{oid}
AND COALESCE(l.last_followup_at, l.assigned_at, l.create_time) >= (CURRENT_TIMESTAMP - (#{idleHours} || ' hours')::interval) AND COALESCE(l.last_followup_at, l.assigned_at, l.create_time) < (CURRENT_TIMESTAMP - ((#{idleHours} - #{imminentHours}) || ' hours')::interval) ORDER BY poolEtaHours ASC LIMIT #{limit}

SELECT o.opty_id AS optyId, COALESCE(o.name, o.full_name) AS optyName, COALESCE(o.user_id::text, o.owner) AS ownerId, o.owner AS ownerName, o.stage AS stage, o.close_reason AS closeReason, COALESCE(o.amount, 0) AS amount, COALESCE(o.update_time, o.create_time) AS lastFollowupAt FROM crm_opty o WHERE COALESCE(o.update_time, o.create_time) < (CURRENT_TIMESTAMP - (#{staleDays} || ' days')::interval)
AND ( (o.user_id IS NOT NULL AND o.user_id::text IN
#{oid}
) OR (o.user_id IS NULL AND o.owner IN
#{oid}
) )
ORDER BY COALESCE(o.update_time, o.create_time) ASC LIMIT #{limit}

SELECT a.pulse_id AS pulseId,
       a.event_type AS eventType,
       a.event_category AS eventCategory,
       a.started_date AS startedDate,
       a.relate_name AS relateName,
       a.subject_type AS subjectType,
       a.subject_id AS subjectId
FROM crm_activity a
WHERE a.user_id::text = #{ownerId}
  AND a.started_date >= #{dayStart}
  AND a.started_date < #{dayEnd}
ORDER BY a.started_date DESC, a.create_time DESC
LIMIT #{limit}
